fn all_prefixes(s: Vec<char>) -> Vec<Vec<char>> {
    let mut result = Vec::new();
    let mut prefix = Vec::new();

    for &c in &s {
        prefix.push(c);
        result.push(prefix.clone());
    }

    result
}

fn main() {
    let input = vec!['a', 'b', 'c'];
    let prefixes = all_prefixes(input);
    for prefix in prefixes {
        println!("{:?}", prefix);
    }
}